// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {LocalSwapPool} from "./LocalSwapPool.sol";

/// @title LocalSwapFactory
/// @notice Permissionless and immutable pool registry. It has no owner or administrative controls.
/// @dev A pair may have one pool per fee tier. The fee is fixed in the pool at
///      creation and can never change, so offering a different fee means creating
///      a separate pool rather than altering an existing one. Nothing here ranks
///      or endorses a tier; callers name the pool they mean.
contract LocalSwapFactory {
    mapping(address => mapping(address => mapping(uint256 => address))) public getPool;
    address[] public allPools;

    error InvalidToken();
    error PoolExists();

    event PoolCreated(
        address indexed token0,
        address indexed token1,
        uint256 indexed feeBasisPoints,
        address pool,
        uint256 poolCount
    );

    function createPool(address tokenA, address tokenB, uint256 feeBasisPoints) external returns (address pool) {
        if (tokenA == address(0) || tokenB == address(0) || tokenA == tokenB) revert InvalidToken();
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        if (getPool[token0][token1][feeBasisPoints] != address(0)) revert PoolExists();

        // The fee is part of the identity: two tiers for one pair are two pools at
        // two addresses, never one address behaving differently at different times.
        bytes32 salt = keccak256(abi.encodePacked(token0, token1, feeBasisPoints));
        // The pool rejects a fee outside its own bounds, so nothing is duplicated here.
        pool = address(new LocalSwapPool{salt: salt}(token0, token1, feeBasisPoints));
        getPool[token0][token1][feeBasisPoints] = pool;
        getPool[token1][token0][feeBasisPoints] = pool;
        allPools.push(pool);
        emit PoolCreated(token0, token1, feeBasisPoints, pool, allPools.length);
    }

    function allPoolsLength() external view returns (uint256) {
        return allPools.length;
    }
}

contracts/LocalSwapPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IERC20Minimal {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

/// @title LocalSwapPool
/// @notice Immutable constant-product pool for one ERC-20 pair. It takes no
///         protocol fee: the swap fee stays in the pool and accrues to the
///         liquidity providers, and no address can withdraw it as revenue.
/// @dev This is original code, intentionally small, and has not been independently audited.
contract LocalSwapPool {
    string public constant name = "LocalSwap LP";
    string public constant symbol = "LS-LP";
    uint8 public constant decimals = 18;
    uint256 public constant MINIMUM_LIQUIDITY = 1_000;

    /// @notice Swap fee in basis points, kept by the pool for its providers.
    /// @dev Without a fee, every arbitrage is a one-way transfer out of the
    ///      providers and nothing ever flows back, so providing liquidity is a
    ///      guaranteed loss. This is not a protocol fee: there is no recipient and
    ///      no address can withdraw it. It is set once at creation and can never
    ///      change, so the factory can offer tiers by creating separate pools.
    uint256 public immutable feeBasisPoints;
    uint256 public constant MINIMUM_FEE_BASIS_POINTS = 1;
    uint256 public constant MAXIMUM_FEE_BASIS_POINTS = 100;
    uint256 private constant BASIS_POINTS = 10_000;

    address public immutable factory;
    address public immutable token0;
    address public immutable token1;

    uint112 private reserve0;
    uint112 private reserve1;
    uint32 private blockTimestampLast;
    uint256 private unlocked = 1;

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    error Expired();
    error InvalidToken();
    error InvalidFee();
    error InvalidRecipient();
    error InsufficientAmount();
    error InsufficientLiquidity();
    error SlippageExceeded();
    error UnsupportedTokenBehavior();
    error TransferFailed();
    error Overflow();
    error Reentrancy();

    event Approval(address indexed owner, address indexed spender, uint256 amount);
    event Transfer(address indexed from, address indexed to, uint256 amount);
    event LiquidityAdded(address indexed sender, address indexed recipient, uint256 amount0, uint256 amount1, uint256 shares);
    event LiquidityRemoved(address indexed sender, address indexed recipient, uint256 amount0, uint256 amount1, uint256 shares);
    event Swap(address indexed sender, address indexed tokenIn, uint256 amountIn, uint256 amountOut, address indexed recipient);
    event Sync(uint112 reserve0, uint112 reserve1);
    event Skim(address indexed sender, address indexed recipient, uint256 amount0, uint256 amount1);

    modifier lock() {
        if (unlocked != 1) revert Reentrancy();
        unlocked = 0;
        _;
        unlocked = 1;
    }

    modifier beforeDeadline(uint256 deadline) {
        if (block.timestamp > deadline) revert Expired();
        _;
    }

    constructor(address tokenA, address tokenB, uint256 feeBasisPoints_) {
        if (tokenA == address(0) || tokenB == address(0) || tokenA == tokenB) revert InvalidToken();
        // A zero fee is rejected on purpose: it leaves providers with no way to be
        // paid at all, which is a property of the pool, not a choice per trade.
        if (feeBasisPoints_ < MINIMUM_FEE_BASIS_POINTS || feeBasisPoints_ > MAXIMUM_FEE_BASIS_POINTS) revert InvalidFee();
        factory = msg.sender;
        feeBasisPoints = feeBasisPoints_;
        (token0, token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
    }

    function getReserves() external view returns (uint112, uint112, uint32) {
        return (reserve0, reserve1, blockTimestampLast);
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            allowance[from][msg.sender] = allowed - amount;
            emit Approval(from, msg.sender, allowance[from][msg.sender]);
        }
        _transfer(from, to, amount);
        return true;
    }

    function quoteExactIn(address tokenIn, uint256 amountIn) public view returns (uint256 amountOut) {
        if (amountIn == 0) revert InsufficientAmount();
        if (tokenIn == token0) return _amountOut(amountIn, reserve0, reserve1);
        if (tokenIn == token1) return _amountOut(amountIn, reserve1, reserve0);
        revert InvalidToken();
    }

    function addLiquidity(
        uint256 amount0,
        uint256 amount1,
        uint256 minShares,
        address recipient,
        uint256 deadline
    ) external lock beforeDeadline(deadline) returns (uint256 shares) {
        if (amount0 == 0 || amount1 == 0) revert InsufficientAmount();
        if (recipient == address(0)) revert InvalidRecipient();

        // Take only what the current ratio can credit. Depositing off-ratio used to
        // leave the surplus in the pool with no shares issued for it, a silent loss
        // to the depositor. Collecting less is safer than refunding: a refund path
        // that ever pays out too much would drain the pool, and this one cannot.
        if (totalSupply != 0) {
            uint256 optimal1 = (amount0 * reserve1) / reserve0;
            if (optimal1 <= amount1) amount1 = optimal1;
            else amount0 = (amount1 * reserve0) / reserve1;
            if (amount0 == 0 || amount1 == 0) revert InsufficientAmount();
        }

        uint256 balance0Before = IERC20Minimal(token0).balanceOf(address(this));
        uint256 balance1Before = IERC20Minimal(token1).balanceOf(address(this));
        _safeTransferFrom(token0, msg.sender, address(this), amount0);
        _safeTransferFrom(token1, msg.sender, address(this), amount1);
        if (
            IERC20Minimal(token0).balanceOf(address(this)) - balance0Before != amount0 ||
            IERC20Minimal(token1).balanceOf(address(this)) - balance1Before != amount1
        ) revert UnsupportedTokenBehavior();

        if (totalSupply == 0) {
            uint256 rootK = _sqrt(amount0 * amount1);
            if (rootK <= MINIMUM_LIQUIDITY) revert InsufficientLiquidity();
            shares = rootK - MINIMUM_LIQUIDITY;
            _mint(address(1), MINIMUM_LIQUIDITY);
        } else {
            shares = _min((amount0 * totalSupply) / reserve0, (amount1 * totalSupply) / reserve1);
        }
        if (shares == 0 || shares < minShares) revert SlippageExceeded();
        _mint(recipient, shares);
        _sync();
        emit LiquidityAdded(msg.sender, recipient, amount0, amount1, shares);
    }

    function removeLiquidity(
        uint256 shares,
        uint256 minAmount0,
        uint256 minAmount1,
        address recipient,
        uint256 deadline
    ) external lock beforeDeadline(deadline) returns (uint256 amount0, uint256 amount1) {
        if (shares == 0) revert InsufficientAmount();
        if (recipient == address(0)) revert InvalidRecipient();
        amount0 = (shares * reserve0) / totalSupply;
        amount1 = (shares * reserve1) / totalSupply;
        if (amount0 == 0 || amount1 == 0) revert InsufficientLiquidity();
        if (amount0 < minAmount0 || amount1 < minAmount1) revert SlippageExceeded();

        _burn(msg.sender, shares);
        _safeTransfer(token0, recipient, amount0);
        _safeTransfer(token1, recipient, amount1);
        _sync();
        emit LiquidityRemoved(msg.sender, recipient, amount0, amount1, shares);
    }

    function swapExactIn(
        address tokenIn,
        uint256 amountIn,
        uint256 minAmountOut,
        address recipient,
        uint256 deadline
    ) external lock beforeDeadline(deadline) returns (uint256 amountOut) {
        if (recipient == address(0) || recipient == address(this)) revert InvalidRecipient();
        // The router already refuses this; the pool must not be the softer door.
        if (minAmountOut == 0) revert SlippageExceeded();
        amountOut = quoteExactIn(tokenIn, amountIn);
        if (amountOut < minAmountOut) revert SlippageExceeded();

        bool zeroForOne = tokenIn == token0;
        address tokenOut = zeroForOne ? token1 : token0;
        uint256 balanceBefore = IERC20Minimal(tokenIn).balanceOf(address(this));
        _safeTransferFrom(tokenIn, msg.sender, address(this), amountIn);
        if (IERC20Minimal(tokenIn).balanceOf(address(this)) - balanceBefore != amountIn) {
            revert UnsupportedTokenBehavior();
        }
        _safeTransfer(tokenOut, recipient, amountOut);
        _sync();
        emit Swap(msg.sender, tokenIn, amountIn, amountOut, recipient);
    }

    /// @notice Records direct token donations in reserves. Anyone may call it.
    function sync() external lock {
        _sync();
    }

    /// @notice Sends any balance held above the recorded reserves to `to`.
    /// @dev Deliberately does not write reserves. `_sync()` reverts once a balance
    ///      passes the uint112 ceiling, and every other state-changing entry point
    ///      ends in `_sync()`, so without a path that still works in exactly that
    ///      state a balance pushed past the ceiling would lock the pool for good
    ///      and strand every liquidity provider. Anyone may call it: the excess is
    ///      not owned by anyone until it has been synced into reserves.
    function skim(address to) external lock {
        if (to == address(0) || to == address(this)) revert InvalidRecipient();
        uint256 excess0 = IERC20Minimal(token0).balanceOf(address(this)) - reserve0;
        uint256 excess1 = IERC20Minimal(token1).balanceOf(address(this)) - reserve1;
        if (excess0 == 0 && excess1 == 0) revert InsufficientAmount();
        if (excess0 != 0) _safeTransfer(token0, to, excess0);
        if (excess1 != 0) _safeTransfer(token1, to, excess1);
        emit Skim(msg.sender, to, excess0, excess1);
    }

    function _amountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut) private view returns (uint256) {
        if (reserveIn == 0 || reserveOut == 0) revert InsufficientLiquidity();
        // The fee is withheld from the input and stays in the pool, so every swap
        // raises the invariant slightly and that gain belongs to the providers.
        uint256 amountInAfterFee = amountIn * (BASIS_POINTS - feeBasisPoints);
        return (amountInAfterFee * reserveOut) / (reserveIn * BASIS_POINTS + amountInAfterFee);
    }

    function _sync() private {
        uint256 balance0Now = IERC20Minimal(token0).balanceOf(address(this));
        uint256 balance1Now = IERC20Minimal(token1).balanceOf(address(this));
        if (balance0Now > type(uint112).max || balance1Now > type(uint112).max) revert Overflow();
        reserve0 = uint112(balance0Now);
        reserve1 = uint112(balance1Now);
        blockTimestampLast = uint32(block.timestamp);
        emit Sync(reserve0, reserve1);
    }

    function _safeTransfer(address token, address to, uint256 amount) private {
        (bool ok, bytes memory data) = token.call(abi.encodeCall(IERC20Minimal.transfer, (to, amount)));
        if (!ok || (data.length != 0 && !abi.decode(data, (bool)))) revert TransferFailed();
    }

    function _safeTransferFrom(address token, address from, address to, uint256 amount) private {
        (bool ok, bytes memory data) = token.call(abi.encodeCall(IERC20Minimal.transferFrom, (from, to, amount)));
        if (!ok || (data.length != 0 && !abi.decode(data, (bool)))) revert TransferFailed();
    }

    function _transfer(address from, address to, uint256 amount) private {
        if (to == address(0)) revert InvalidRecipient();
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        emit Transfer(from, to, amount);
    }

    function _mint(address to, uint256 amount) private {
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function _burn(address from, uint256 amount) private {
        balanceOf[from] -= amount;
        totalSupply -= amount;
        emit Transfer(from, address(0), amount);
    }

    function _min(uint256 a, uint256 b) private pure returns (uint256) {
        return a < b ? a : b;
    }

    function _sqrt(uint256 value) private pure returns (uint256 result) {
        if (value == 0) return 0;
        result = 1 << (_log2(value) >> 1);
        unchecked {
            for (uint256 i; i < 7; ++i) result = (result + value / result) >> 1;
            return result < value / result ? result : value / result;
        }
    }

    function _log2(uint256 value) private pure returns (uint256 result) {
        while (value > 1) {
            value >>= 1;
            result++;
        }
    }
}

contracts/LocalSwapRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IERC20RouterMinimal {
    function balanceOf(address account) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

interface ILocalSwapPool {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112, uint112, uint32);
    function addLiquidity(
        uint256 amount0,
        uint256 amount1,
        uint256 minShares,
        address recipient,
        uint256 deadline
    ) external returns (uint256 shares);
    function quoteExactIn(address tokenIn, uint256 amountIn) external view returns (uint256 amountOut);
    function swapExactIn(
        address tokenIn,
        uint256 amountIn,
        uint256 minAmountOut,
        address recipient,
        uint256 deadline
    ) external returns (uint256 amountOut);
}

/// @title LocalSwapRouter
/// @notice Stateless, atomic exact-input routing across at most four LocalSwap pools.
/// @dev The frontend accepts this router only when its deployed runtime hash matches the bundled artifact.
contract LocalSwapRouter {
    uint256 public constant MAX_HOPS = 4;
    uint256 private unlocked = 1;

    error Expired();
    error InvalidAmount();
    error InvalidPath();
    error InvalidRecipient();
    error SlippageExceeded();
    error TransferFailed();
    error UnsupportedTokenBehavior();
    error Reentrancy();

    event RoutedSwap(
        address indexed sender,
        address indexed tokenIn,
        address indexed tokenOut,
        uint256 amountOut
    );

    event RoutedLiquidity(
        address indexed sender,
        address indexed pool,
        address indexed recipient,
        uint256 amount0,
        uint256 amount1,
        uint256 shares
    );

    modifier lock() {
        if (unlocked != 1) revert Reentrancy();
        unlocked = 0;
        _;
        unlocked = 1;
    }

    function quoteExactIn(
        address[] calldata pools,
        address tokenIn,
        uint256 amountIn
    ) external view returns (uint256 amountOut, address tokenOut) {
        _validatePathLength(pools.length);
        if (tokenIn == address(0) || amountIn == 0) revert InvalidAmount();
        address[] memory visitedTokens = new address[](pools.length + 1);
        visitedTokens[0] = tokenIn;
        tokenOut = tokenIn;
        amountOut = amountIn;
        for (uint256 i; i < pools.length; ++i) {
            _assertUniquePool(pools, i);
            tokenOut = _nextToken(pools[i], tokenOut);
            _assertUniqueToken(visitedTokens, i + 1, tokenOut);
            visitedTokens[i + 1] = tokenOut;
            amountOut = ILocalSwapPool(pools[i]).quoteExactIn(visitedTokens[i], amountOut);
            if (amountOut == 0) revert InvalidAmount();
        }
    }

    function swapExactIn(
        address[] calldata pools,
        address tokenIn,
        uint256 amountIn,
        uint256 minAmountOut,
        address recipient,
        uint256 deadline
    ) external lock returns (uint256 amountOut, address tokenOut) {
        _validatePathLength(pools.length);
        if (block.timestamp > deadline) revert Expired();
        if (tokenIn == address(0) || amountIn == 0 || minAmountOut == 0) revert InvalidAmount();
        if (recipient == address(0) || recipient == address(this)) revert InvalidRecipient();

        uint256 inputBefore = IERC20RouterMinimal(tokenIn).balanceOf(address(this));
        _safeTransferFrom(tokenIn, msg.sender, address(this), amountIn);
        if (IERC20RouterMinimal(tokenIn).balanceOf(address(this)) - inputBefore != amountIn) {
            revert UnsupportedTokenBehavior();
        }

        address[] memory visitedTokens = new address[](pools.length + 1);
        visitedTokens[0] = tokenIn;
        tokenOut = tokenIn;
        amountOut = amountIn;

        for (uint256 i; i < pools.length; ++i) {
            address pool = pools[i];
            _assertUniquePool(pools, i);
            address currentToken = tokenOut;
            tokenOut = _nextToken(pool, currentToken);
            _assertUniqueToken(visitedTokens, i + 1, tokenOut);
            visitedTokens[i + 1] = tokenOut;
            if (i + 1 == pools.length) {
                amountOut = _executeHop(pool, currentToken, tokenOut, amountOut, minAmountOut, recipient, deadline);
            } else {
                // Bind an intermediate hop to its own quote rather than to zero.
                // Nothing can move the reserves between this read and the swap —
                // both pools and this router hold their locks for the whole call —
                // so an exact bound here can never revert a hop that was going to
                // succeed, and an unbounded hop is never sent.
                uint256 hopMinimum = ILocalSwapPool(pool).quoteExactIn(currentToken, amountOut);
                amountOut = _executeHop(pool, currentToken, tokenOut, amountOut, hopMinimum, address(this), deadline);
            }
        }

        if (amountOut < minAmountOut) revert SlippageExceeded();
        emit RoutedSwap(msg.sender, tokenIn, tokenOut, amountOut);
    }

    function _nextToken(address pool, address tokenIn) private view returns (address tokenOut) {
        if (pool == address(0)) revert InvalidPath();
        address token0 = ILocalSwapPool(pool).token0();
        address token1 = ILocalSwapPool(pool).token1();
        if (token0 == address(0) || token1 == address(0) || token0 == token1) revert InvalidPath();
        if (tokenIn == token0) return token1;
        if (tokenIn == token1) return token0;
        revert InvalidPath();
    }

    function _executeHop(
        address pool,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minimumOut,
        address recipient,
        uint256 deadline
    ) private returns (uint256 receivedOut) {
        _safeApprove(tokenIn, pool, 0);
        _safeApprove(tokenIn, pool, amountIn);
        uint256 outputBefore = IERC20RouterMinimal(tokenOut).balanceOf(recipient);
        uint256 returnedOut = ILocalSwapPool(pool).swapExactIn(
            tokenIn,
            amountIn,
            minimumOut,
            recipient,
            deadline
        );
        receivedOut = IERC20RouterMinimal(tokenOut).balanceOf(recipient) - outputBefore;
        if (receivedOut != returnedOut || IERC20RouterMinimal(tokenIn).allowance(address(this), pool) != 0) {
            revert UnsupportedTokenBehavior();
        }
    }

    function _assertUniquePool(address[] calldata pools, uint256 index) private pure {
        for (uint256 i; i < index; ++i) if (pools[i] == pools[index]) revert InvalidPath();
    }

    /// @notice What `addLiquidity` would pull right now, at the current reserves.
    /// @dev The screen has to tell a depositor what the pool will actually take,
    ///      because off-ratio amounts are trimmed. Computing that in the frontend
    ///      means two implementations of one rule, and they drift. This is the same
    ///      settlement the deposit performs, so the number shown comes from the code
    ///      that will run. It is still a quote: reserves move, and the deposit
    ///      settles again against the reserves it actually meets.
    function quoteAddLiquidity(
        address pool,
        uint256 amount0Desired,
        uint256 amount1Desired
    ) external view returns (uint256 amount0, uint256 amount1) {
        if (pool == address(0)) revert InvalidPath();
        if (amount0Desired == 0 || amount1Desired == 0) revert InvalidAmount();
        (uint112 reserve0, uint112 reserve1, ) = ILocalSwapPool(pool).getReserves();
        return _settleRatio(amount0Desired, amount1Desired, reserve0, reserve1);
    }

    /// @notice Deposits into `pool` at the ratio that holds when this call executes.
    /// @dev The pool credits only what its current ratio allows and leaves the rest
    ///      untaken. A caller who approves what they typed is therefore left with an
    ///      allowance standing on the pool for the difference — measured at 300 JADE
    ///      for a 100 / 500 deposit into a 1 : 2 pool. Computing the ratio in the
    ///      frontend does not fix it: reserves move between the read and the mined
    ///      transaction, so the amounts go stale and the residue returns.
    ///
    ///      Settling the ratio here is the only place it can be settled against the
    ///      reserves that will actually be used. Exactly the settled amounts are
    ///      pulled, so nothing is over-approved and nothing is left behind.
    ///
    ///      The router holds no balance: everything pulled in this call is deposited
    ///      in the same call, and the shares are minted straight to `recipient`.
    function addLiquidity(
        address pool,
        uint256 amount0Desired,
        uint256 amount1Desired,
        uint256 amount0Min,
        uint256 amount1Min,
        uint256 minShares,
        address recipient,
        uint256 deadline
    ) external lock returns (uint256 amount0, uint256 amount1, uint256 shares) {
        if (block.timestamp > deadline) revert Expired();
        if (pool == address(0)) revert InvalidPath();
        if (recipient == address(0) || recipient == address(this)) revert InvalidRecipient();
        if (amount0Desired == 0 || amount1Desired == 0) revert InvalidAmount();
        // A zero floor accepts any ratio the reserves happen to hold when this is
        // mined, which is the same unguarded shape the pool refuses for a swap.
        if (amount0Min == 0 || amount1Min == 0 || minShares == 0) revert SlippageExceeded();

        (uint112 reserve0, uint112 reserve1, ) = ILocalSwapPool(pool).getReserves();
        (amount0, amount1) = _settleRatio(amount0Desired, amount1Desired, reserve0, reserve1);
        if (amount0 < amount0Min || amount1 < amount1Min) revert SlippageExceeded();

        // Split out because the token addresses and the post-conditions do not fit
        // in this frame alongside eight parameters.
        shares = _deposit(pool, amount0, amount1, minShares, recipient, deadline);
        emit RoutedLiquidity(msg.sender, pool, recipient, amount0, amount1, shares);
    }

    function _deposit(
        address pool,
        uint256 amount0,
        uint256 amount1,
        uint256 minShares,
        address recipient,
        uint256 deadline
    ) private returns (uint256 shares) {
        address token0 = ILocalSwapPool(pool).token0();
        address token1 = ILocalSwapPool(pool).token1();
        _safeTransferFrom(token0, msg.sender, address(this), amount0);
        _safeTransferFrom(token1, msg.sender, address(this), amount1);
        _safeApprove(token0, pool, amount0);
        _safeApprove(token1, pool, amount1);

        shares = ILocalSwapPool(pool).addLiquidity(amount0, amount1, minShares, recipient, deadline);

        // The pool must have taken all of it. If it took less, this router is
        // holding tokens that belong to the caller, and an approval it granted is
        // still standing — the exact pair of problems this function exists to remove.
        if (
            IERC20RouterMinimal(token0).balanceOf(address(this)) != 0 ||
            IERC20RouterMinimal(token1).balanceOf(address(this)) != 0 ||
            IERC20RouterMinimal(token0).allowance(address(this), pool) != 0 ||
            IERC20RouterMinimal(token1).allowance(address(this), pool) != 0
        ) revert UnsupportedTokenBehavior();
    }

    /// @dev Mirrors the pool's own rounding, so the amounts pulled are exactly the
    ///      amounts it will credit. An empty pool takes both sides whole.
    function _settleRatio(
        uint256 amount0Desired,
        uint256 amount1Desired,
        uint256 reserve0,
        uint256 reserve1
    ) private pure returns (uint256 amount0, uint256 amount1) {
        if (reserve0 == 0 || reserve1 == 0) return (amount0Desired, amount1Desired);
        uint256 optimal1 = (amount0Desired * reserve1) / reserve0;
        if (optimal1 <= amount1Desired) return (amount0Desired, optimal1);
        uint256 optimal0 = (amount1Desired * reserve0) / reserve1;
        return (optimal0, amount1Desired);
    }

    function _assertUniqueToken(address[] memory visited, uint256 count, address token) private pure {
        for (uint256 i; i < count; ++i) if (visited[i] == token) revert InvalidPath();
    }

    function _validatePathLength(uint256 length) private pure {
        if (length == 0 || length > MAX_HOPS) revert InvalidPath();
    }

    function _safeApprove(address token, address spender, uint256 amount) private {
        (bool ok, bytes memory data) = token.call(abi.encodeCall(IERC20RouterMinimal.approve, (spender, amount)));
        if (!ok || (data.length != 0 && !abi.decode(data, (bool)))) revert TransferFailed();
    }

    function _safeTransferFrom(address token, address from, address to, uint256 amount) private {
        (bool ok, bytes memory data) = token.call(abi.encodeCall(IERC20RouterMinimal.transferFrom, (from, to, amount)));
        if (!ok || (data.length != 0 && !abi.decode(data, (bool)))) revert TransferFailed();
    }
}
